from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def max_nesting_level(s: str) -> int:
        max_level = current_level = 0
        for char in s:
            if char == '(':
                current_level += 1
                max_level = max(max_level, current_level)
            elif char == ')':
                current_level -= 1
                # Check for negative current_level to handle unbalanced parentheses
                if current_level < 0:
                    raise ValueError("Unbalanced parentheses in the input string")
        # Check if parentheses are balanced at the end
        if current_level != 0:
            raise ValueError("Unbalanced parentheses in the input string")
        return max_level

    groups = paren_string.split()
    return [max_nesting_level(group) for group in groups]

