initial_code:
from typing import List

def parse_music(music_string: str) -> List[int]:
    note_map = {
        'o': 4,
        'o|': 2,
        '.|': 1
    }
    notes = music_string.split()
    result = []
    i = 0
    while i < len(notes):
        if notes[i] in note_map:
            result.append(note_map[notes[i]])
            i += 1
        else:
            # Handle potential multi-character notes by checking combinations
            if notes[i] + '|' in note_map:
                result.append(note_map[notes[i] + '|'])
                i += 2
            else:
                # If no match, skip and move to next (error handling for unknown notes)
                i += 1
    return result

