initial_code:
def largest_prime_factor(n: int) -> int:
    """Return the largest prime factor of n. Assume n > 1 and is not a prime.

    >>> largest_prime_factor(13195)
    29
    >>> largest_prime_factor(2048)
    2
    """
    def is_prime(num: int) -> bool:
        """Check if a number is prime."""
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    # Start checking from the smallest possible prime factor
    for i in range(2, n + 1):
        # If i is a factor of n and is prime
        if n % i == 0 and is_prime(i):
            # Check if i is the largest prime factor by ensuring n / i has no prime factors greater than i
            temp = n // i
            while temp > 1:
                if temp % i == 0:
                    temp //= i
                elif is_prime(temp) and temp > i:
                    # If a larger prime factor is found, return it
                    return temp
                else:
                    # If temp is not divisible by i and is not a larger prime, break
                    break
            # If no larger prime factor is found, i is the largest prime factor
            return i

