        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    # Start checking from the largest possible factor down to 2
    for i in range(n, 1, -1):
        # If i is a factor of n and is prime
        if n % i == 0 and is_prime(i):
            # Since we're checking from largest to smallest, the first prime factor we find is the largest
            return i

