def is_multiply_prime(a):
    """Check if a number is the multiplication of 3 prime numbers."""
    if a >= 100:
        return False

    for i in range(2, a):
        if a % i == 0 and is_prime(i):
            for j in range(i, a // i):
                if (a // i) % j == 0 and is_prime(j) and is_prime(a // (i * j)):
                    return True
    return False

