def is_simple_power(x, n):
    """Returns true if a number x is a simple power of n and false in other cases."""
    if x <= 0 or n <= 0:
        return False
    if n == 1:
        return x == 1
    log_result = math.log(x, n)
    return log_result.is_integer()

