import math

def is_simple_power(x, n):
    """Returns true if a number x is a simple power of n and false in other cases."""
    if x <= 0 or n <= 0:
        return False
    if n == 1:
        return x == 1
    if x == 1:  # Added check for x == 1 to handle case where log(1, n) is 0 for any n
        return True
    try:
        log_result = math.log(x, n)
    except ValueError:  # Handle case where n is 1 (already covered) or x is negative (also covered)
        return False
    return log_result.is_integer()

