initial_code:
def encode(message):
    """
    Encodes a message by swapping the case of all letters and replacing vowels with the letter two places ahead in the alphabet.

    Args:
        message (str): The input message to be encoded.

    Returns:
        str: The encoded message.
    """
    vowels = 'aeiouAEIOU'
    encoded_message = ''

    for char in message:
        if char.isalpha():
            # Swap case
            if char.islower():
                char = char.upper()
            else:
                char = char.lower()

            # Replace vowels with the letter two places ahead
            if char in vowels:
                if char.islower():
                    char = chr((ord(char) - ord('a') + 2) % 26 + ord('a'))
                else:
                    char = chr((ord(char) - ord('A') + 2) % 26 + ord('A'))

            encoded_message += char
        else:
            encoded_message += char

    return encoded_message

