def count_up_to(n):
    """Returns an array of the first n integers that are prime numbers and less than n."""
    def is_prime(num):
        """Check if a number is prime."""
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    primes = []
    num = 2
    while len(primes) < n:
        if is_prime(num):
            primes.append(num)
        num += 1
        if num >= n:
            break
    return primes

