initial_code:
def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test:
        return {}

    # Split the string into a list of characters and count occurrences
    char_count = {}
    for char in test.split():
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the maximum count
    max_count = max(char_count.values())

    # Filter the dictionary to include only characters with the maximum count
    result = {char: count for char, count in char_count.items() if count == max_count}

    return result

