def order_by_points(nums):
    """
    Sorts the given list of integers in ascending order according to the sum of their digits.
    If there are several items with similar sum of their digits, orders them based on their index in the original list.

    Args:
        nums (list): A list of integers.

    Returns:
        list: The sorted list of integers based on the sum of their digits and original index.
    """
    def sum_of_digits(n):
        """Helper function to calculate the sum of digits of a number."""
        return sum(int(digit) for digit in str(abs(n)))

    # Use the sorted function with a custom key that returns a tuple.
    # The first element of the tuple is the sum of digits, and the second is the original index.
    # This ensures that items with the same sum of digits are ordered by their original index.
    return sorted(enumerate(nums), key=lambda x: (sum_of_digits(x[1]), x[0]))


# Since the sorted function returns a list of tuples (index, value), we need to extract the values.
# We use a list comprehension to achieve this.
def order_by_points(nums):
    def sum_of_digits(n):
        return sum(int(digit) for digit in str(abs(n)))

    return [x[1] for x in sorted(enumerate(nums), key=lambda x: (sum_of_digits(x[1]), x[0]))]

